-- Files people attach to a meeting, and stills of its video pinned to it, each a frozen copy kept
-- with the meeting. See docs/meetings.md, Attachments and frames.
--
-- A file arrives as an upload's parts, as a capture's recording does, and the engine stores it and
-- reads its text. A frame arrives whole, a still a person took from the player or segmenting took
-- from the recording. Either is pinned to ranges of the final transcript by marks of kind `pin`,
-- which is how it travels with the excerpts over those ranges.
CREATE TABLE meeting_attachments (
    -- UUIDv7, generated by the API.
    id UUID PRIMARY KEY,
    -- No cascade, as on `page_attachments`: this row is the only record of a file kept with a
    -- provider, so nothing may drop it by accident. Meetings are never deleted for good.
    meeting_id UUID NOT NULL REFERENCES meetings (id),
    -- `file` for a file a person attached, `frame` for a still of a capture's video.
    kind TEXT NOT NULL CHECK (kind IN ('file', 'frame')),
    -- Where it is kept: the location page attachments use, as it was chosen when it arrived, so
    -- changing the choice moves nothing.
    storage_location_id UUID NOT NULL
        CONSTRAINT meeting_attachments_storage_location REFERENCES storage_locations (id),
    -- Relative to the location's directory. NULL while an upload's parts wait to be stored.
    storage_path TEXT CHECK (char_length(storage_path) BETWEEN 1 AND 1024),
    -- When it was stored, which is when it can be served.
    stored_at TIMESTAMPTZ,
    -- The name people see, cleaned of anything a path or a header could read as more than a name.
    file_name TEXT NOT NULL CHECK (char_length(file_name) BETWEEN 1 AND 200),
    -- The type it is served as, set from its extension by the API's one table, never from what
    -- the browser that sent it said.
    content_type TEXT NOT NULL CHECK (char_length(content_type) BETWEEN 1 AND 200),
    size_bytes BIGINT NOT NULL CHECK (size_bytes > 0),
    -- A frame's capture and its moment on that capture's own clock, in milliseconds. The
    -- capture's offset places it on the meeting's.
    capture_id UUID REFERENCES meeting_captures (id),
    capture_ms BIGINT CHECK (capture_ms >= 0),
    -- What a frame shows, as whoever pinned it put it. Indexed with the meeting.
    caption TEXT CHECK (char_length(caption) BETWEEN 1 AND 1000),
    -- A frame's difference hash: 256 bits of which way its picture's brightness runs across a 17
    -- by 16 grid (`crate::images::fingerprint`), which near duplicates share but for a few bits.
    fingerprint BYTEA CHECK (octet_length(fingerprint) = 32),
    -- The text read from a file, for search: `pending` until it is read, `read` once it is (an
    -- empty text for a file that holds none), `none` for a kind of file with no text to read, and
    -- `unreadable` for one that could not be read.
    text TEXT,
    text_state TEXT NOT NULL CHECK (text_state IN ('pending', 'read', 'none', 'unreadable')),
    -- Who attached it, and the agent acting for them, as on `meeting_marks`.
    created_by UUID NOT NULL REFERENCES users (id),
    agent TEXT CHECK (char_length(agent) BETWEEN 1 AND 300),
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- The change of the meeting's history that removed it, NULL while it stands. Its file stays
    -- with the provider, so an undo puts it back at the same address.
    removed_by UUID REFERENCES meeting_events (id),
    CONSTRAINT meeting_attachments_stored CHECK ((stored_at IS NULL) = (storage_path IS NULL)),
    CONSTRAINT meeting_attachments_agent_named_with_its_agent CHECK (
        agent IS NOT NULL OR agent_name IS NULL
    ),
    -- A frame is a still of one capture at one moment, with its caption and fingerprint; a file
    -- has none of them.
    CONSTRAINT meeting_attachments_frame CHECK (
        (kind = 'frame') = (capture_id IS NOT NULL)
        AND (kind = 'frame') = (capture_ms IS NOT NULL)
        AND (kind = 'frame') = (caption IS NOT NULL)
        AND (kind = 'frame') = (fingerprint IS NOT NULL)
    ),
    CONSTRAINT meeting_attachments_text_read CHECK ((text IS NOT NULL) = (text_state = 'read'))
);

-- A meeting's page lists what it holds, in the order it arrived.
CREATE INDEX meeting_attachments_of_meeting ON meeting_attachments (meeting_id, id);

-- Deleting a location refuses while files are in it, and the search for them starts from it.
CREATE INDEX meeting_attachments_location ON meeting_attachments (storage_location_id);

-- The largest file a meeting takes, an admin's choice: 1 GB unless they choose another, and never
-- more than a storage provider takes in one upload (5 GiB, `crate::storage::MAX_UPLOAD_BYTES`).
ALTER TABLE workspace_settings
    ADD COLUMN meeting_attachment_max_bytes BIGINT NOT NULL DEFAULT 1000000000
        CONSTRAINT workspace_settings_meeting_attachment_max_bytes
            CHECK (meeting_attachment_max_bytes BETWEEN 1 AND 5368709120);

-- A file attached to a meeting arrives as an upload, in parts, as a recording does: its upload
-- names the attachment it became, as a capture's names its capture.
ALTER TABLE meeting_uploads
    ADD COLUMN attachment_id UUID UNIQUE REFERENCES meeting_attachments (id);

ALTER TABLE meeting_uploads DROP CONSTRAINT meeting_uploads_finished;
ALTER TABLE meeting_uploads ADD CONSTRAINT meeting_uploads_finished CHECK (
    (finished_at IS NULL) = (capture_id IS NULL AND attachment_id IS NULL)
    AND (capture_id IS NULL OR attachment_id IS NULL)
);

-- An attachment is always to a meeting there is.
ALTER TABLE meeting_uploads ADD CONSTRAINT meeting_uploads_attachment_to_a_meeting CHECK (
    attachment_id IS NULL OR meeting_id IS NOT NULL
);

ALTER TABLE meeting_upload_files DROP CONSTRAINT meeting_upload_files_kind_check;
ALTER TABLE meeting_upload_files ADD CONSTRAINT meeting_upload_files_kind_check
    CHECK (kind IN ('recording', 'transcript', 'attachment'));
